// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type GraphWalkProps = Record<string, any>;

// The relative points defining the graph shape (x: 0-1, y: 0-1 where 1 is 100%)
const GRAPH_POINTS = [
  { x: 0.0, y: 1.0 },   // Start (100%)
  { x: 0.33, y: 0.88 }, // End of initial flat walk
  { x: 0.5, y: 0.45 },  // Steep drop
  { x: 0.68, y: 0.2 },  // Softening
  { x: 0.85, y: 0.08 }, // Almost flat
  { x: 1.0, y: 0.0 },   // End (0%)
];

// Helper to interpolate Y and calculate slope on the path given an X coordinate
const getPathDataAtX = (targetX: number, screenPoints: { x: number; y: number }[]) => {
  if (targetX <= screenPoints[0].x) return { y: screenPoints[0].y, slope: 0 };
  if (targetX >= screenPoints[screenPoints.length - 1].x) {
    return { y: screenPoints[screenPoints.length - 1].y, slope: 0 };
  }

  for (let i = 0; i < screenPoints.length - 1; i++) {
    const p1 = screenPoints[i];
    const p2 = screenPoints[i + 1];
    if (targetX >= p1.x && targetX <= p2.x) {
      const progress = (targetX - p1.x) / (p2.x - p1.x);
      const y = p1.y + progress * (p2.y - p1.y);
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      const slope = Math.atan2(dy, dx); // in radians
      return { y, slope };
    }
  }
  return { y: 0, slope: 0 };
};

const Limb: React.FC<{
  rotation: number; // degrees
  length: number;
  thickness: number;
  color: string;
}> = ({ rotation, length, thickness, color }) => (
  <line
    x1={0}
    y1={0}
    x2={0}
    y2={length}
    stroke={color}
    strokeWidth={thickness}
    strokeLinecap="round"
    transform={`rotate(${rotation})`}
  />
);

const GraphWalk: React.FC<GraphWalkProps> = ({
  backgroundColor = "#0a0e14",
  transparentBackground = false,
  durationInSeconds = 8,
  graphLineColor = "#f030c0",
  gridColor = "rgba(255, 255, 255, 0.15)",
  textColor = "#8892b0",
  stickmanColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const totalFrames = durationInSeconds * fps;

  // Layout calculations
  const padLeft = width * 0.1;
  const padRight = width * 0.08;
  const padTop = height * 0.15;
  const padBottom = height * 0.15;
  const graphWidth = width - padLeft - padRight;
  const graphHeight = height - padTop - padBottom;

  // Map normalized points to screen coordinates
  const screenPoints = GRAPH_POINTS.map((p) => ({
    x: padLeft + p.x * graphWidth,
    y: padTop + (1 - p.y) * graphHeight,
  }));

  // Build SVG path string
  const pathD = screenPoints
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
    .join(" ");

  // Calculate approximate path length for drawing animation
  const pathLength = screenPoints.reduce((acc, curr, i, arr) => {
    if (i === 0) return 0;
    const prev = arr[i - 1];
    return acc + Math.hypot(curr.x - prev.x, curr.y - prev.y);
  }, 0);

  // Animation Timings
  const t_drawEnd = totalFrames * 0.15;
  const t_walkStart = t_drawEnd + 10;
  const t_walkEnd = totalFrames * 0.45;
  const t_slideStart = t_walkEnd;
  const t_slideEnd = totalFrames * 0.85;
  const t_standEnd = t_slideEnd + 15;

  // 1. Graph Drawing
  const drawProgress = interpolate(frame, [0, t_drawEnd], [0, pathLength], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.2, 0, 0, 1),
  });

  // 2. Stickman Position X
  const walkEndX = screenPoints[1].x;
  const finalX = screenPoints[screenPoints.length - 1].x;
  let currentX = screenPoints[0].x;

  if (frame > t_walkStart && frame <= t_walkEnd) {
    currentX = interpolate(frame, [t_walkStart, t_walkEnd], [screenPoints[0].x, walkEndX]);
  } else if (frame > t_slideStart) {
    currentX = interpolate(frame, [t_slideStart, t_slideEnd], [walkEndX, finalX], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.4, 0, 0.2, 1), // Accelerate then smooth stop
    });
  }

  // 3. Stickman Position Y and Slope
  const { y: baseCurrentY, slope } = getPathDataAtX(currentX, screenPoints);

  // Drop-in animation at start
  const dropProgress = spring({
    frame: frame - (t_walkStart - 15),
    fps,
    config: { damping: 12, mass: 0.8 },
  });
  const dropOffset = interpolate(dropProgress, [0, 1], [-200, 0], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  const opacity = interpolate(frame, [t_walkStart - 15, t_walkStart - 5], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // 4. Kinematics (Angles in degrees)
  // State Blenders
  const isSliding = interpolate(frame, [t_slideStart, t_slideStart + 15], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  const isStanding = interpolate(frame, [t_slideEnd, t_standEnd], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  const blendVal = (a: number, b: number, factor: number) => a + (b - a) * factor;

  // Pitch calculation for headfirst dive (rotates entire stickman group)
  const slopeDeg = (slope * 180) / Math.PI;
  const targetSlidePitch = 90 + slopeDeg; // 90 aligns torso horizontally, adding slope aligns with ground

  let currentPitch = blendVal(0, targetSlidePitch, isSliding);
  currentPitch = blendVal(currentPitch, 0, isStanding);

  // Walk Cycle
  const walkSpeed = 0.3;
  const walkCycle = (frame - t_walkStart) * walkSpeed;
  const walkAmp = interpolate(frame, [t_walkStart, t_walkStart + 10], [0, 45], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  }); // ease into walk
  
  // Base Poses
  // Walk (0 = straight down, - is forward/right, + is backward/left)
  const poseWalk = {
    frontLeg: Math.sin(walkCycle) * -walkAmp,
    backLeg: Math.sin(walkCycle + Math.PI) * -walkAmp,
    frontArm: Math.sin(walkCycle + Math.PI) * -30,
    backArm: Math.sin(walkCycle) * -30,
    body: 5,
    offsetY: -35 + Math.abs(Math.sin(walkCycle)) * -4, // bounce
  };

  // Dive / Fall (Headfirst slide matching the reference shape)
  const poseSlide = {
    frontLeg: -5,    // Legs tight and straight
    backLeg: 5,      
    frontArm: -15,   // Arms swept back, trailing behind the pitch
    backArm: 15,
    body: 0,         // Straight body (rotation handled globally via pitch)
    offsetY: -8,     // Close to the line
  };

  // Stand (Idle)
  const poseStand = {
    frontLeg: -5,
    backLeg: 5,
    frontArm: -10,
    backArm: 10,
    body: 0,
    offsetY: -35,
  };
  
  // First blend Walk -> Slide
  let currentPose = {
    frontLeg: blendVal(poseWalk.frontLeg, poseSlide.frontLeg, isSliding),
    backLeg: blendVal(poseWalk.backLeg, poseSlide.backLeg, isSliding),
    frontArm: blendVal(poseWalk.frontArm, poseSlide.frontArm, isSliding),
    backArm: blendVal(poseWalk.backArm, poseSlide.backArm, isSliding),
    body: blendVal(poseWalk.body, poseSlide.body, isSliding),
    offsetY: blendVal(poseWalk.offsetY, poseSlide.offsetY, isSliding),
  };

  // Then blend (Walk/Slide) -> Stand
  currentPose = {
    frontLeg: blendVal(currentPose.frontLeg, poseStand.frontLeg, isStanding),
    backLeg: blendVal(currentPose.backLeg, poseStand.backLeg, isStanding),
    frontArm: blendVal(currentPose.frontArm, poseStand.frontArm, isStanding),
    backArm: blendVal(currentPose.backArm, poseStand.backArm, isStanding),
    body: blendVal(currentPose.body, poseStand.body, isStanding),
    offsetY: blendVal(currentPose.offsetY, poseStand.offsetY, isStanding),
  };

  const finalY = baseCurrentY + currentPose.offsetY + dropOffset;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Background SVG Grid and Path */}
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0 }}>
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="8" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Grid Lines */}
        {[0, 0.5, 1].map((ratio, i) => {
          const yPos = padTop + ratio * graphHeight;
          return (
            <line
              key={`grid-${i}`}
              x1={padLeft}
              y1={yPos}
              x2={width - padRight}
              y2={yPos}
              stroke={gridColor}
              strokeWidth={2}
            />
          );
        })}

        {/* Graph Line */}
        <path
          d={pathD}
          fill="none"
          stroke={graphLineColor}
          strokeWidth={8}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter="url(#glow)"
          strokeDasharray={pathLength}
          strokeDashoffset={pathLength - drawProgress}
        />

        {/* Stickman */}
        {frame >= t_walkStart - 15 && (
          <g
            transform={`translate(${currentX}, ${finalY}) rotate(${currentPitch})`}
            opacity={opacity}
          >
            {/* Back Arm */}
            <g transform="translate(0, -32)">
              <Limb rotation={currentPose.backArm} length={22} thickness={4} color={stickmanColor} />
            </g>
            
            {/* Back Leg */}
            <Limb rotation={currentPose.backLeg} length={28} thickness={5} color={stickmanColor} />
            
            {/* Body Group (rotates from hips) */}
            <g transform={`rotate(${currentPose.body})`}>
              {/* Torso */}
              <line
                x1={0} y1={0} x2={0} y2={-32}
                stroke={stickmanColor} strokeWidth={6} strokeLinecap="round"
              />
              {/* Head */}
              <circle cx={0} cy={-42} r={9} fill={stickmanColor} />
            </g>

            {/* Front Leg */}
            <Limb rotation={currentPose.frontLeg} length={28} thickness={5} color={stickmanColor} />

            {/* Front Arm (Attached) */}
            <g transform="translate(0, -32)">
              <Limb rotation={currentPose.frontArm} length={22} thickness={4} color={stickmanColor} />
            </g>
          </g>
        )}
      </svg>

      {/* HTML Text Labels */}
      {/* Y-Axis */}
      {["100%", "50%", "0"].map((label, i) => (
        <div
          key={label}
          style={{
            position: "absolute",
            left: padLeft - 24,
            top: padTop + (i * 0.5) * graphHeight,
            transform: "translate(-100%, -50%)",
            color: textColor,
            fontSize: 32,
            fontWeight: 500,
            letterSpacing: "-0.02em",
          }}
        >
          {label}
        </div>
      ))}

      {/* X-Axis */}
      <div
        style={{
          position: "absolute",
          left: padLeft,
          top: padTop + graphHeight + 32,
          transform: "translateX(-50%)",
          color: textColor,
          fontSize: 32,
          fontWeight: 500,
        }}
      >
        0:00
      </div>
      <div
        style={{
          position: "absolute",
          left: width - padRight,
          top: padTop + graphHeight + 32,
          transform: "translateX(-50%)",
          color: textColor,
          fontSize: 32,
          fontWeight: 500,
        }}
      >
        0:33
      </div>
    </AbsoluteFill>
  );
};

export default GraphWalk;